import React, {useState, useEffect} from 'react';
import { Box, Typography, IconButton } from '@mui/material';
import TwitterIcon from '@mui/icons-material/Twitter';
import TelegramIcon from '@mui/icons-material/Telegram';
import FacebookIcon from '@mui/icons-material/Facebook';
import axios from 'axios';

const Footer = () => {

  const [siteName, setSiteName] = useState(null);
  const [twitterText, setTwitterText] = useState(null);
  const [facebookText, setFacebookText] = useState(null);
  const [telegramText, setTelegramText] = useState(null);

  const fetchData = async () => {
      try {
        const response = await axios.get('data.json');
        setSiteName(response.data[0].value);
        setTwitterText(response.data[1].value);
        setFacebookText(response.data[2].value);
        setTelegramText(response.data[3].value);
      } catch (error) {
        console.error('Error fetching data:', error);
      }
    };

    useEffect(() => {
    fetchData();
  });

  return (
    <Box
      sx={{
        backgroundColor: '#0b1e35',
        color: '#fff',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: '16px',
        borderTop: '1px solid #333',
      }}
    >
      {/* Left Side: Copyright Text */}
      <Typography variant="body2" sx={{ fontSize: '14px' }}>
        © {new Date().getFullYear()} {siteName}. All Rights Reserved.
      </Typography>

      {/* Right Side: Social Media Links */}
      <Box sx={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
        <IconButton
          component="a"
          href={twitterText}
          target="_blank"
          rel="noopener noreferrer"
          sx={{ color: '#fff' }}
        >
          <TwitterIcon />
        </IconButton>
        <IconButton
          component="a"
          href={telegramText}
          target="_blank"
          rel="noopener noreferrer"
          sx={{ color: '#fff' }}
        >
          <TelegramIcon />
        </IconButton>
        <IconButton
          component="a"
          href={facebookText}
          target="_blank"
          rel="noopener noreferrer"
          sx={{ color: '#fff' }}
        >
          <FacebookIcon />
        </IconButton>
      </Box>
    </Box>
  );
};

export default Footer;
